body{
  background-color: #24341b;
  font-family: "cormorant-garamond", serif;
  color: #ffffff;
  line-height: 1.4;
  font-weight: 300;
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* ------------------------------
   NAVBAR MOBILE-FIRST
------------------------------ */

#main-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  padding: 14px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(0,0,0,0.25);
  backdrop-filter: blur(10px);
  z-index: 999;
}

/* LOGO */
#logo img {
  width: 24px;        /* rimpicciolito */
  filter: brightness(0) invert(1); /* diventa bianco */
  opacity: 0.95;       /* leggero soft touch */
}

/* HAMBURGER */
#hamburger {
  width: 28px;
  height: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
}

#hamburger span {
  height: 3px;
  background: white;
}

/* MENU MOBILE */
#main-nav {
  display: none;
  position: absolute;
  top: 60px;
  right: 20px;
  background: #4E513B;
  padding: 18px;
  flex-direction: column;
  gap: 14px;
}

#main-nav a {
  font-family: "acumin-pro", sans-serif;
  font-weight: 400;
  font-style: normal;
  color: #F7F6F0;
  text-decoration: none;
  text-transform: uppercase;
}

#main-nav.open {
  display: flex;
  background: rgba(0,0,0,0.25);
  backdrop-filter: blur(10px);
}

/* BACK LINK (solo pagine secondarie) */
.back-link {
  display: block;
  margin-top: 80px;
  margin-left: 20px;
  color: #F7F6F0;
  font-size: 1rem;
  text-decoration: none;
  opacity: 0.8;
}

.back-link:hover {
  opacity: 1;
}

/* ------------------------------
   MEMORYLANE SECTION — MOBILE FIRST
------------------------------ */

#memorylane-section {
  background: #24341b;
  padding: 60px 20px;
  display: flex;
  justify-content: center;
  color: #ffffff;
  font-family: "acumin-pro", sans-serif;
}

.memorylane-card {
  max-width: 600px;
  width: 100%;
  margin: 0 auto;
  text-align: center;
  background: transparent;
  padding: 0;
}

/* Titolo */
.memorylane-card h2 {
  font-family: "cormorant-garamond", serif;
  font-weight: 400;
  font-style: normal;
  font-size: 3.2rem;
  margin-bottom: 20px;
  color: #ffffff;
}

/* Intro */
.memorylane-intro {
  font-size: 1.1rem;
  margin-bottom: 30px;
  opacity: 0.9;
}

/* Instructions */
.instructions {
  text-align: left;
  margin-bottom: 30px;
}

.step {
  display: flex;
  align-items: flex-start;
  margin-bottom: 20px;
  gap: 15px;
}

.step-number {
  background: #ffffff;
  color: #24341b;
  font-weight: bold;
  font-size: 1.2rem;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.step p {
  margin: 0;
  line-height: 1.4;
  font-size: 1rem;
}

.qr-code {
  max-width: 150px;
  margin: 10px 0;
  border: 2px solid #ffffff;
  border-radius: 8px;
}

/* Nota finale */
.memorylane-note {
  font-size: 1rem;
  opacity: 0.9;
  font-style: italic;
}

/* ------------------------------
   DESKTOP (≥ 768px)
------------------------------ */
@media (min-width: 768px) {

  #memorylane-section {
    padding: 100px 20px;
  }

  .memorylane-card h2 {
    font-size: 5rem;
    margin-bottom: 30px;
  }

  .memorylane-intro {
    font-size: 1.3rem;
    margin-bottom: 40px;
  }

  .step p {
    font-size: 1.1rem;
  }

  .qr-code {
    max-width: 200px;
  }

  .memorylane-note {
    font-size: 1.1rem;
  }
}

/* ------------------------------
   DESKTOP NAVBAR
------------------------------ */
@media (min-width: 768px) {

  /* Nascondi hamburger */
  #hamburger {
    display: none;
  }

  /* Navbar orizzontale */
  #main-nav {
    display: flex !important;
    position: static;
    flex-direction: row;
    gap: 40px;
    background: transparent;
    padding: 0;
  }

  #main-nav a {
    color: #F7F6F0;
    font-size: 0.8rem;
    position: relative;
    padding-bottom: 4px;
  }

  /* Underline animato */
  #main-nav a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 0;
    width: 0%;
    height: 2px;
    background: white;
    transition: width 0.3s ease;
  }

  #main-nav a:hover::after {
    width: 100%;
  }

  /* Back link più elegante su desktop */
  .back-link {
    margin-left: 40px;
    font-size: 1.1rem;
  }
}

footer {
  color: black;
  background: #F7F6F0;
  text-align: center;
  padding: 40px 0;
  font-size: 0.9rem;
}

const header = document.getElementById('main-header');
const mainNavLinks = document.querySelectorAll('#main-nav a');

window.addEventListener('scroll', () => {
  const scrollY = window.scrollY;

  // Cambia colore header con dissolvenza
  if(scrollY > 50){
    header.classList.add('scrolled');
  } else {
    header.classList.remove('scrolled');
  }
});


  const hamburger = document.getElementById("hamburger");
  const nav = document.getElementById("main-nav");

  hamburger.addEventListener("click", () => {
    nav.classList.toggle("open");
  });

  // Chiudi menu mobile quando clicchi un link
  document.querySelectorAll("#main-nav a").forEach(link => {
    link.addEventListener("click", () => {
      nav.classList.remove("open");
    });
  });
